def transform(grid):
    g=[row[:] for row in grid]
    # Uniform full 8-lines partition the grid into panels. Marker 3 selects
    # horizontal panel bands; marker 2 selects vertical panel bands.
    h=[r for r,row in enumerate(g) if all(x==8 for x in row)]
    w=len(g[0])
    v=[c for c in range(w) if all(row[c]==8 for row in g)]
    rbounds=[-1]+h+[len(g)]
    cbounds=[-1]+v+[w]
    rpanels=[(rbounds[i]+1,rbounds[i+1]) for i in range(len(rbounds)-1)]
    cpanels=[(cbounds[i]+1,cbounds[i+1]) for i in range(len(cbounds)-1)]
    rsel={i for i,(a,b) in enumerate(rpanels) if any(3 in g[r][a:b] for r in range(a,b))}
    csel={i for i,(a,b) in enumerate(cpanels) if any(g[r][c]==2 for r in range(len(g)) for c in range(a,b))}
    for ri,(ra,rz) in enumerate(rpanels):
        for ci,(ca,cz) in enumerate(cpanels):
            color=6 if ri in rsel and ci in csel else 3 if ri in rsel else 2 if ci in csel else 0
            if color:
                for r in range(ra,rz):
                    for c in range(ca,cz): g[r][c]=color
    return g

